<?php
/**
 * DCAI 授权系统 V1.3 数据库迁移（幂等，可重复执行；MySQL 5.6 兼容）
 * 用法: php install/migrate_v1.3.php
 *
 * 新增能力：
 *  1. 机器码/硬件指纹绑定（防授权码多机共用）
 *     - licenses 增加 machine_limit（最大绑定机器数）
 *     - 新表 machine_bindings（授权码×机器码 绑定关系）
 *     - instances 增加 machine_code（实例所属机器指纹）
 *  2. 试用模式（Trial）
 *     - licenses 增加 trial_days（0=非试用；N=首次注册免费 N 天）
 *  3. 离线激活（内网断网场景）
 *     - 新表 offline_activations（管理员签发的离线激活文件）
 */
require_once dirname(__DIR__) . '/core/Bootstrap.php';

$db = dcai_db();
$pdo = $db->pdo();

function dcai13_table_exists(PDO $pdo, string $table): bool
{
    $stmt = $pdo->query("SELECT COUNT(*) FROM information_schema.TABLES
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '$table'");
    return (int)$stmt->fetchColumn() > 0;
}

function dcai13_column_exists(PDO $pdo, string $table, string $col): bool
{
    $stmt = $pdo->query("SELECT COUNT(*) FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = '$table' AND COLUMN_NAME = '$col'");
    return (int)$stmt->fetchColumn() > 0;
}

$ok = 0;

// ---------- 1. licenses 增加 machine_limit（最大绑定机器数，默认 1 保持既有行为） ----------
if (!dcai13_column_exists($pdo, 'licenses', 'machine_limit')) {
    $pdo->exec("ALTER TABLE `licenses` ADD COLUMN `machine_limit` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT '最大绑定机器数(0=不限制)' AFTER `max_instances`");
    echo "licenses.machine_limit added\n"; $ok++;
} else {
    echo "licenses.machine_limit exists\n";
}

// ---------- 2. licenses 增加 trial_days（试用模式） ----------
if (!dcai13_column_exists($pdo, 'licenses', 'trial_days')) {
    $pdo->exec("ALTER TABLE `licenses` ADD COLUMN `trial_days` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '试用天数(0=正式授权; N=首次注册免费试用N天)' AFTER `machine_limit`");
    echo "licenses.trial_days added\n"; $ok++;
} else {
    echo "licenses.trial_days exists\n";
}

// ---------- 3. products 增加试用开放开关与默认试用天数 ----------
if (!dcai13_column_exists($pdo, 'products', 'trial_enabled')) {
    $pdo->exec("ALTER TABLE `products` ADD COLUMN `trial_enabled` TINYINT NOT NULL DEFAULT 0 COMMENT '1=开放自助申请试用 0=不开放' AFTER `sale_icon`");
    echo "products.trial_enabled added\n"; $ok++;
} else {
    echo "products.trial_enabled exists\n";
}
if (!dcai13_column_exists($pdo, 'products', 'trial_days')) {
    $pdo->exec("ALTER TABLE `products` ADD COLUMN `trial_days` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT '产品默认试用天数' AFTER `trial_enabled`");
    echo "products.trial_days added\n"; $ok++;
} else {
    echo "products.trial_days exists\n";
}

// ---------- 4. instances 增加 machine_code（实例所属机器指纹） ----------
if (!dcai13_column_exists($pdo, 'instances', 'machine_code')) {
    $pdo->exec("ALTER TABLE `instances` ADD COLUMN `machine_code` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '机器指纹(HMAC-SHA256摘要)' AFTER `ip`");
    echo "instances.machine_code added\n"; $ok++;
} else {
    echo "instances.machine_code exists\n";
}

// ---------- 5. machine_bindings 机器码绑定关系 ----------
if (!dcai13_table_exists($pdo, 'machine_bindings')) {
    $pdo->exec("CREATE TABLE IF NOT EXISTS `machine_bindings` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `license_id` INT UNSIGNED NOT NULL COMMENT '授权码ID',
  `machine_code` VARCHAR(64) NOT NULL COMMENT '机器指纹(HMAC-SHA256)',
  `machine_name` VARCHAR(255) NOT NULL DEFAULT '' COMMENT '机器名称(如 hostname)',
  `first_instance_id` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '首个绑定实例ID',
  `first_seen_at` DATETIME NOT NULL,
  `last_seen_at` DATETIME DEFAULT NULL,
  `status` TINYINT NOT NULL DEFAULT 1 COMMENT '1=绑定 0=已解绑',
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_license_machine` (`license_id`,`machine_code`),
  KEY `idx_license` (`license_id`),
  KEY `idx_machine` (`machine_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='机器码绑定'");
    echo "machine_bindings table ready\n"; $ok++;
} else {
    echo "machine_bindings exists\n";
}

// ---------- 6. offline_activations 离线激活记录 ----------
if (!dcai13_table_exists($pdo, 'offline_activations')) {
    $pdo->exec("CREATE TABLE IF NOT EXISTS `offline_activations` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `license_id` INT UNSIGNED NOT NULL COMMENT '授权码ID',
  `product_id` INT UNSIGNED NOT NULL DEFAULT 0,
  `machine_code` VARCHAR(64) NOT NULL COMMENT '机器指纹',
  `machine_name` VARCHAR(255) NOT NULL DEFAULT '',
  `request_id` VARCHAR(64) NOT NULL DEFAULT '' COMMENT '激活请求ID',
  `expire_at` DATETIME NULL COMMENT '离线授权到期时间(NULL=随授权码)',
  `activate_file` TEXT COMMENT '签发的激活文件内容(JSON, 含RSA签名)',
  `status` TINYINT NOT NULL DEFAULT 1 COMMENT '1=已签发 0=已作废',
  `created_by` INT UNSIGNED DEFAULT NULL COMMENT '签发管理员ID',
  `created_at` DATETIME NOT NULL,
  `updated_at` DATETIME NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_req_machine` (`request_id`,`machine_code`),
  KEY `idx_license` (`license_id`),
  KEY `idx_machine` (`machine_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='离线激活记录'");
    echo "offline_activations table ready\n"; $ok++;
} else {
    echo "offline_activations exists\n";
}

// ---------- 7. 写入 Python SDK 文件（V1.3 新增） ----------
// 说明：升级包内不直接存放 .py（旧版系统升级白名单不含 py 会拒绝上传），
// 而在迁移落盘阶段由本脚本写入 sdk/dcai_client.py 与 sdk/dcai_config.sample.py。
// 幂等：每次执行覆盖写入最新版 SDK 内容，无副作用。
$sdkSources = [
    'sdk/dcai_client.py'          => '',
    'sdk/dcai_config.sample.py'   => '',
];
foreach ($sdkSources as $rel => $b64) {
    $content = base64_decode($b64, true);
    if ($content === false || $content === '') {
        echo "$rel base64 解码失败, skipped\n";
        continue;
    }
    $target = dirname(__DIR__) . '/' . $rel;
    if (!is_dir(dirname($target))) {
        @mkdir(dirname($target), 0755, true);
    }
    if (@file_put_contents($target, $content, LOCK_EX) !== false) {
        echo "$rel written (" . strlen($content) . " bytes)\n";
        $ok++;
    } else {
        echo "$rel 写入失败\n";
    }
}

echo "\nMIGRATE V1.3 DONE. changes=$ok\n";
